// Local GraphQL Code Generator plugin: emits the backend schema as a string constant so the
// in-browser mock layer (SchemaLink) executes queries against exactly the same schema.
const { printSchema } = require('graphql');

module.exports = {
  plugin(schema) {
    return [
      '/* eslint-disable */',
      '// GENERATED by `npm run codegen` from backend/src/main/resources/graphql/schema.graphqls – do not edit.',
      `export const typeDefs = ${JSON.stringify(printSchema(schema))};`,
      '',
    ].join('\n');
  },
};
